def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    if n >= 15:
        recent = history[-15:]
        d_count = 0
        for _, o in recent:
            if o == 'D':
                d_count += 1
        if d_count > 4:
            return 'D'
    last_m, last_o = history[-1]
    if last_o == 'C':
        return 'C'
    streak = 0
    for _, o in reversed(history):
        if o == 'D':
            streak += 1
        else:
            break
    if streak == 1:
        return 'C'
    if streak == 2:
        return 'D'
    if streak == 3:
        return 'C'
    if streak == 4:
        return 'C'
    return 'D'
